style.css:
@-moz-document domain("roblox.com") {
/* Base background and font */
body, html {
    background: linear-gradient(135deg, #0f0, #1b5e20) !important;
    color: #ffffff !important;
    font-family: "Comic Sans MS", cursive !important;
}

/* Links */
a, a:visited {
    color: #ffff00 !important;
    font-weight: bold !important;
    text-shadow: 0 0 5px #ff0 !important;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #ccff00 !important;
    text-shadow: 1px 1px 2px #000 !important;
}

/* Buttons */
button, .btn-primary, .btn-secondary, .btn {
    background-color: #00ff00 !important;
    color: #000000 !important;
    border: 2px solid #ffff00 !important;
    box-shadow: 0 0 15px #0f0, inset 0 0 5px #ff0 !important;
    text-transform: uppercase !important;
}

/* Navbar & Header */
nav, .navbar, header, .top-nav, #navigation-container, #header {
    background-color: #003300 !important;
    border-bottom: 3px solid #00ff00 !important;
}

/* Inputs and forms */
input, textarea, select {
    background-color: #101010 !important;
    color: #00ff00 !important;
    border: 2px solid #00ff00 !important;
    box-shadow: 0 0 5px #0f0 !important;
}

/* Images */
img {
    filter: contrast(1.2) saturate(2) drop-shadow(0 0 5px lime) !important;
    border: 2px dashed #00ff00 !important;
}

/* Footer */
footer, #footer {
    background-color: #000000 !important;
    color: #00ff00 !important;
    border-top: 3px solid #00ff00 !important;
}

/* Game cards */
.game-card-container {
    background-color: #002200 !important;
    border: 1px solid #00ff00 !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 12px;
}
::-webkit-scrollbar-track {
    background: #002200 !important;
}
::-webkit-scrollbar-thumb {
    background-color: #00ff00 !important;
    border: 2px solid #003300 !important;
}

/* Dew logo spinner */
body::before {
    content: " ";
    position: fixed;
    top: 10px;
    right: 10px;
    width: 100px;
    height: 100px;
    background-image: url("https://upload.wikimedia.org/wikipedia/en/1/1e/Mountain_Dew_logo.svg");
    background-size: contain;
    background-repeat: no-repeat;
    z-index: 9999;
    animation: spin 10s linear infinite;
    opacity: 0.7;
    pointer-events: none;
}

/* Animation */
@keyframes spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}
}
